/** Actual legacy DB with no spell-text status table; does not claim newly decoded or complete spell values. */
public final class LegacySpellTooltipAcceptance {
 public static void main(String[] args)throws Exception{
  JournalSnapshots.out=Path.of(args[1]);Files.createDirectories(JournalSnapshots.out);var report=JournalSnapshots.report;report.add("Exact JAR SHA256: "+JournalSnapshots.hash(Path.of(args[0])));report.add("Scope: actual legacy compactDB item1176 Smelling Salts, raw $q1 variable and missing status table. No completeness or newly decoded-value claim.");int exit=0;
  try{
   try(var db=Database.open(Path.of(System.getProperty("wowforever.database")))){try(var statement=db.connection().createStatement();var rows=statement.executeQuery("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='spell_text_evidence'")){JournalSnapshots.check(rows.next()&&rows.getInt(1)==0,"Actual legacy database has no spell_text_evidence table");}var loaded=(dev.wowforever.app.ui.detail.DetailPanels.LoadedItem)dev.wowforever.app.ui.detail.DetailPanels.load(new EntityRef(EntityKind.ITEM,1176),Repositories.of(db)).orElseThrow();JournalSnapshots.check(loaded.detail().card().lines().stream().anyMatch(line->line.text()!=null&&line.text().contains("$q1")&&line.evidence().status().equals("UNKNOWN")),"Actual item1176 raw token retains UNKNOWN evidence status");}
   dev.wowforever.app.Main.main(new String[0]);ResearchAcceptance.until(()->JournalSnapshots.edt(()->{JournalSnapshots.frame=Arrays.stream(Window.getWindows()).filter(w->w instanceof MainFrame&&w.isShowing()).map(MainFrame.class::cast).findFirst().orElse(null);return JournalSnapshots.frame!=null&&JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(JournalHomePage.class::isInstance);}),"actual Main Home");JournalSnapshots.robot=new Robot();JournalSnapshots.robot.setAutoDelay(55);var field=MainFrame.class.getDeclaredField("controller");field.setAccessible(true);JournalSnapshots.controller=(AppController)field.get(JournalSnapshots.frame);
   for(var mode:ThemeManager.Mode.values()){JournalHeaderAcceptance.selectTheme(mode);for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{JournalSnapshots.frame.setBounds(20,20,width,900);return null;});JournalSnapshots.edt(()->{JournalSnapshots.controller.open(new dev.wowforever.app.nav.ViewTarget.Home());return null;});JournalSnapshots.waitFor(JournalHomePage.class);ResearchAcceptance.open(EntityKind.ITEM,1176);JToggleButton toggle=JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JToggleButton b&&b.isShowing()&&"In-game tooltip".equals(b.getText())).map(JToggleButton.class::cast).findFirst().orElseThrow());JournalSnapshots.click(toggle);JournalSnapshots.waitFor(TooltipLinesPanel.class);TooltipLinesPanel tooltip=JournalSnapshots.find(TooltipLinesPanel.class);String visible=JournalSnapshots.edt(()->JournalSnapshots.texts(tooltip));JournalSnapshots.check(visible.contains("70 health and ? mana")&&!visible.contains("$q1"),"Actual unresolved spell variable is masked in visible tooltip "+mode+" "+width);JournalSnapshots.check(visible.contains("Spell-text completeness unknown"),"Legacy missing status is visibly qualified UNKNOWN "+mode+" "+width);JournalSnapshots.check(JournalSnapshots.edt(()->JournalSnapshots.all(tooltip).stream().filter(JComponent.class::isInstance).map(JComponent.class::cast).anyMatch(c->c.getToolTipText()!=null&&c.getToolTipText().contains("Spell-text status: UNKNOWN")&&c.getToolTipText().contains("$q1"))),"Retained tooltip evidence preserves raw token and UNKNOWN status");JComponent status=JournalSnapshots.edt(()->JournalSnapshots.all(tooltip).stream().filter(c->c instanceof javax.swing.text.JTextComponent text&&text.getText().contains("Spell-text completeness unknown")).map(JComponent.class::cast).findFirst().orElseThrow());JournalSnapshots.edt(()->{status.scrollRectToVisible(new Rectangle(0,0,status.getWidth(),status.getHeight()));return null;});JournalSnapshots.check(JournalSnapshots.edt(()->status.getVisibleRect().height>0),"UNKNOWN spell-text qualification is inside the visible tooltip viewport");JournalSnapshots.snap("item1176-legacy-tooltip-"+mode.name().toLowerCase()+"-"+width);}}
  }catch(Throwable failure){report.add("FAIL: "+failure);failure.printStackTrace();exit=1;}finally{Files.write(JournalSnapshots.out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(exit);
 }
}
